with payments_by_order as (select order_id, sort_array(collect_set(method)) as method_list, round((100 * sum(case when method = 'paypal' then 1 else 0 end)) / count(*), 1) as pct_paypal from payments where method in ('promptpay', 'paypal', 'cash') group by order_id) select o.discount, o.store_id, pbo.method_list, pbo.pct_paypal from orders o inner join payments_by_order pbo on o.id = pbo.order_id where pbo.pct_paypal > 65
